// 这个夹具复现一个实测过的假阳性（`dsh-mnemon` 的形态）：
// 服务是通过**导出的数组**声明的，而不是运行时调 `ctx.provide()`。
//
//   const provide = ["vaultService"]
//   export { apply, inject, name, provide }
//
// 只认 `ctx.provide(...)` 的话，这个服务会被当成"无人提供"，
// 于是**消费者**被报成「部分可用 / 依赖的服务由其它插件提供，当前 profile 里没有提供方」
// —— 而提供方就在同一个 node_modules 里。工具把"装好了"报成了"缺依赖"。
export { apply }

const provide = ['vaultService']

function apply(ctx) {
  ctx.effect(() => {
    ctx.provide('vaultService', {
      find: async (id) => ({ id }),
    })
  })
}

export { name, provide }

const name = '@fixture/provideexported'
